-- New rooms, preferences, search and operations with real APIs; all changes ROLLBACK.
begin;
-- The launch flag turns on only in the rolled-back test transaction.
update public.feature_flags set is_enabled=true,rollout_percent=100 where key='community.enabled';
do $$
declare owner_user public.users; reader public.users; owner_claims text; reader_claims text;
  s uuid; invite_s uuid; request_s uuid; c uuid; private_c uuid; role_id uuid; msg_id uuid; second_msg uuid;
  result jsonb; draft jsonb; rejected boolean; old_count integer; tokenv text:=encode(extensions.gen_random_bytes(32),'hex');
begin
  select * into owner_user from public.users where username='site_owner';
  select * into reader from public.users where username='denemeuser';
  if owner_user.id is null or reader.auth_user_id is null then raise exception 'Test hesapları bulunamadı.'; end if;
  owner_claims:=jsonb_build_object('sub',owner_user.auth_user_id,'role','authenticated','session_id',coalesce(owner_user.active_session_id,gen_random_uuid()))::text;
  reader_claims:=jsonb_build_object('sub',reader.auth_user_id,'role','authenticated','session_id',coalesce(reader.active_session_id,gen_random_uuid()))::text;
  delete from public.user_blocks where blocker_id in (owner_user.id,reader.id) and blocked_id in (owner_user.id,reader.id);
  perform set_config('request.jwt.claims',owner_claims,true);
  select count(*) into old_count from community_v2.servers where owner_id=owner_user.id and fansub_id is null;
  update community_v2.operations_config set rooms_per_owner=old_count+3 where id;
  s:=(public.community_v2_rooms('create','{"name":"Okuma kulübü doğrulaması","join_mode":"open"}')->>'id')::uuid;
  invite_s:=(public.community_v2_rooms('create','{"name":"Davetli okuma doğrulaması","join_mode":"invite"}')->>'id')::uuid;
  request_s:=(public.community_v2_rooms('create','{"name":"Başvurulu okuma doğrulaması","join_mode":"request"}')->>'id')::uuid;
  rejected:=false; begin perform public.community_v2_rooms('create','{"name":"Kota doğrulaması","join_mode":"open"}'); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Oda kotası aşılabildi.'; end if;
  if not community_v2.is_owner(s,owner_user.id) or not community_v2.is_member(s,owner_user.id) then raise exception 'Oda sahipliği/üyeliği bozuk.'; end if;
  result:=public.community_v2_read('home','{}');
  if not (result->'servers') @> jsonb_build_array(jsonb_build_object('id',s,'kind','room')) then raise exception 'Oda ana listede yok.'; end if;
  result:=public.community_v2_read('server',jsonb_build_object('server_id',s));
  c:=(result->'channels'->0->>'id')::uuid;
  if result->'profile'->>'name'<>'Okuma kulübü doğrulaması' or (result->'channels'->0->>'can_link_series')::boolean then raise exception 'Oda profili/seri ayrımı bozuk.'; end if;
  private_c:=(public.community_v2_write('save_channel',jsonb_build_object('server_id',s,'name','Özel okuma doğrulaması','position',20,'is_private',true,'role_ids','[]'::jsonb))->>'id')::uuid;
  role_id:=(public.community_v2_write('save_role',jsonb_build_object('server_id',s,'name','Okur doğrulaması','color','#82d4c9','position',20,'permissions',array['messages.reply','mentions.users'],'icon','📚','hoist',true))->>'id')::uuid;
  result:=public.community_v2_personal('role_preview',jsonb_build_object('server_id',s,'role_ids',array[role_id]));
  if result->'channels' @> jsonb_build_array(jsonb_build_object('id',private_c)) or not result->'permissions' @> '["messages.read","messages.reply"]'::jsonb then raise exception 'Rol önizlemesi/OR hatalı.'; end if;
  perform set_config('request.jwt.claims',reader_claims,true);
  rejected:=false; begin perform public.community_v2_read('server',jsonb_build_object('server_id',s)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Üye olmayan özel sunucu verisi okudu.'; end if;
  result:=public.community_v2_read('discover','{"search":"doğrulaması"}');
  if result @> jsonb_build_array(jsonb_build_object('id',invite_s)) then raise exception 'Davetli oda keşfette sızdı.'; end if;
  rejected:=false; begin perform public.community_v2_write('join',jsonb_build_object('server_id',invite_s)); exception when raise_exception then rejected:=true; end;
  if not rejected then raise exception 'Davetsiz katılım açığı.'; end if;
  result:=public.community_v2_write('join',jsonb_build_object('server_id',request_s));
  if result->>'pending'<>'true' or community_v2.is_member(request_s,reader.id) then raise exception 'Başvuru izinsiz üyelik verdi.'; end if;
  perform public.community_v2_write('join',jsonb_build_object('server_id',s));
  perform public.community_v2_rooms('nickname',jsonb_build_object('server_id',s,'nickname','Kitap dostu'));
  perform public.community_v2_personal('save_preferences','{"auto_join":true,"notifications":"all","push_enabled":false,"show_presence":true,"show_typing":true}');
  result:=public.community_v2_personal('heartbeat',jsonb_build_object('channel_id',c,'typing',true));
  if not result @> jsonb_build_array(jsonb_build_object('user_id',reader.id,'name','Kitap dostu','typing',true)) then raise exception 'Çevrimiçi/takma ad bilgisi yanlış.'; end if;
  rejected:=false; begin perform public.community_v2_personal('heartbeat',jsonb_build_object('channel_id',private_c,'typing',true)); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Özel kanal presence açığı.'; end if;
  rejected:=false; begin perform public.community_v2_operations('status'); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Normal üye işletim ayarlarına erişti.'; end if;
  perform set_config('request.jwt.claims',owner_claims,true);
  perform public.community_v2_rooms('decide_request',jsonb_build_object('server_id',request_s,'user_id',reader.id,'approve',true));
  if not community_v2.is_member(request_s,reader.id) then raise exception 'Başvuru onayı çalışmadı.'; end if;
  msg_id:=(public.community_v2_write('send',jsonb_build_object('channel_id',c,'client_id',gen_random_uuid(),'body','Yeni bölüm üzerine okuma buluşması. <@'||reader.id||'>'))->>'id')::uuid;
  if community_v2.deliver_notifications()<0 then raise exception 'Bildirim işi başarısız.'; end if;
  if not exists(select 1 from public.notifications where user_id=reader.id and data->>'message_id'=msg_id::text and title='Toplulukta yeni mesaj') then raise exception 'Bildirim teslim edilmedi.'; end if;
  if exists(select 1 from public.notifications where data->>'message_id'=msg_id::text and message like '%okuma buluşması%') then raise exception 'Özel metin bildirime taşındı.'; end if;
  perform set_config('request.jwt.claims',reader_claims,true);
  result:=public.community_v2_personal('search',jsonb_build_object('channel_id',c,'search','bölüm'));
  if not result @> jsonb_build_array(jsonb_build_object('id',msg_id)) then raise exception 'Arama mesajı bulamadı.'; end if;
  perform public.community_v2_personal('save_scope',jsonb_build_object('server_id',s,'mode','off'));
  if community_v2.notification_mode(reader.id,s,c)<>'off' then raise exception 'Sunucu bildirimi kapatılamadı.'; end if;
  perform public.community_v2_personal('save_scope',jsonb_build_object('channel_id',c,'mode','mentions'));
  if community_v2.notification_mode(reader.id,s,c)<>'mentions' then raise exception 'Kanal tercihi devralmayı ezmedi.'; end if;
  perform public.community_v2_personal('save_scope',jsonb_build_object('server_id',s,'mode','inherit','muted_until',now()+interval '1 hour'));
  if community_v2.notification_mode(reader.id,s,c)<>'off' then raise exception 'Süreli sunucu sessizliği aşıldı.'; end if;
  insert into public.user_blocks(blocker_id,blocked_id) values(reader.id,owner_user.id) on conflict do nothing;
  result:=public.community_v2_read('messages',jsonb_build_object('channel_id',c));
  if result->0->>'body'<>'' or result->0->>'blocked'<>'true' then raise exception 'Engellenmiş mesaj gizlenmedi.'; end if;
  if public.community_v2_personal('search',jsonb_build_object('channel_id',c,'search','bölüm'))<>'[]'::jsonb then raise exception 'Engellenmiş hesap aramada sızdı.'; end if;
  perform public.community_v2_personal('save_preferences','{"auto_join":true,"notifications":"mentions","push_enabled":false,"show_presence":false,"show_typing":false}');
  if exists(select 1 from community_v2.presence where user_id=reader.id) then raise exception 'Görünmezlik anlık uygulanmadı.'; end if;
  perform set_config('request.jwt.claims',owner_claims,true);
  perform public.community_v2_rooms('offer_transfer',jsonb_build_object('server_id',s,'user_id',reader.id,'version',1));
  perform set_config('request.jwt.claims',reader_claims,true);
  perform public.community_v2_rooms('accept_transfer',jsonb_build_object('server_id',s));
  if not community_v2.is_owner(s,reader.id) or community_v2.is_owner(s,owner_user.id) then raise exception 'Tek sahip devri bozuk.'; end if;
  perform public.community_v2_rooms('archive',jsonb_build_object('server_id',s,'version',3,'archived',true));
  rejected:=false; begin perform public.community_v2_write('send',jsonb_build_object('channel_id',c,'client_id',gen_random_uuid(),'body','Arşiv yazma doğrulaması')); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'Arşiv yazmaya açık.'; end if;
  if jsonb_array_length(public.community_v2_read('messages',jsonb_build_object('channel_id',c)))<>1 then raise exception 'Arşiv geçmişi kayboldu.'; end if;
  perform public.community_v2_rooms('archive',jsonb_build_object('server_id',s,'version',4,'archived',false));
  update community_v2.audit set created_at=now()-interval '181 days' where server_id=s;
  if community_v2.maintenance()<0 then raise exception 'Temizlik işi başarısız.'; end if;
  if exists(select 1 from community_v2.audit where server_id=s) then raise exception 'Saklama temizliği çalışmadı.'; end if;
  if not exists(select 1 from community_v2.messages where id=msg_id) then raise exception 'Normal mesaj geçmişi silindi.'; end if;
  if has_function_privilege('anon','public.community_v2_rooms(text,jsonb)','execute') or has_function_privilege('authenticated','community_v2.deliver_notifications()','execute') then raise exception 'API yetki sınırı açık.'; end if;
end $$;
select 'Topluluk genişleme regresyonu PASS' result;
rollback;
